// Grounded preparation on a fictional generation connection, with remote narratives disabled.
async fn queued_questionnaire(c:&mut PgConnection,work:&Value,question:&str,resumes:&automated_apply_agents::private_resume::Settings)->Value{questionnaire_observe(c,work,questionnaire_report(work,question),resumes).await.unwrap()}
async fn questionnaire_prepare(c:&mut PgConnection,resumes:&automated_apply_agents::private_resume::Settings)->Result<bool>{let packets=packet_settings();let answers=answer_settings();automated_apply_agents::execution::questionnaire_preparation::prepare_one(c,automated_apply_agents::execution::questionnaire_preparation::Services{packets:&packets,answers:&answers,narratives:None,resumes}).await}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_idle_questionnaire_preparation_does_not_wait_for_owner_control(){
    let(mut c,_work,resumes)=questionnaire_fixture().await;let before=browser_snapshot(&mut c).await;let mut other=connection().await;let mut held=other.begin().await.unwrap();sqlx::query("SELECT key FROM owner_preferences WHERE key='agent_conversation:primary' FOR UPDATE").execute(&mut *held).await.unwrap();sqlx::query("SET lock_timeout='100ms'").execute(&mut c).await.unwrap();assert!(!questionnaire_prepare(&mut c,&resumes).await.unwrap());assert_eq!(browser_snapshot(&mut c).await,before);held.rollback().await.unwrap();
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_questionnaire_preparation_resolves_confirmed_fact_and_binds_evidence_before_refresh_without_an_extra_apply(){
    let(mut c,work,resumes)=questionnaire_fixture().await;queued_questionnaire(&mut c,&work,"What is your full name?",&resumes).await;let name:String=sqlx::query_scalar("SELECT full_name FROM candidate_profiles WHERE singleton_key='primary'").fetch_one(&mut c).await.unwrap();assert!(questionnaire_prepare(&mut c,&resumes).await.unwrap());let current=browser_pref(&mut c,&format!("apply_work:{}",work["id"].as_str().unwrap())).await;assert_eq!(current["operation"],"refresh_questionnaire_profile");assert_eq!(current["status"],"queued");assert_eq!(current["questionnaire_answer"]["answer"],name);assert_eq!(current["questionnaire_answer"]["resolved_source"],"candidate_profile");assert!(current["questionnaire_answer"]["context_generation"].is_string());assert!(current["questionnaire_answer"]["project_digest"].is_string());assert_eq!(current["admitted_actions"],work["admitted_actions"]);assert!(current["permit_expires_at"].is_null());assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM owner_preferences WHERE starts_with(key,'exec_q:')").fetch_one(&mut c).await.unwrap(),0);assert!(!questionnaire_prepare(&mut c,&resumes).await.unwrap());
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_questionnaire_preparation_missing_fact_creates_scoped_owner_question_without_inventing_a_value(){
    let(mut c,work,resumes)=questionnaire_fixture().await;queued_questionnaire(&mut c,&work,"What is your notice period in days?",&resumes).await;assert!(questionnaire_prepare(&mut c,&resumes).await.unwrap());let current=browser_pref(&mut c,&format!("apply_work:{}",work["id"].as_str().unwrap())).await;assert_eq!(current["status"],"waiting");assert_eq!(current["reason"],"questionnaire_verified_answer_required");assert!(current["questionnaire_answer"].is_null());let questions:Vec<Value>=sqlx::query_scalar("SELECT value FROM owner_preferences WHERE starts_with(key,'exec_q:')").fetch_all(&mut c).await.unwrap();assert_eq!(questions.len(),1);assert_eq!(questions[0]["queue_work_id"],work["id"]);assert_eq!(questions[0]["state"],"pending");assert_eq!(questions[0]["reuse_approved"],false);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_questionnaire_preparation_known_fact_outside_displayed_choices_does_not_invent_or_ask_for_an_override(){
    let(mut c,work,resumes)=questionnaire_fixture().await;let mut report=questionnaire_report(&work,"What is your full name?");report["questionnaire"]["answer_kind"]=json!("choice");report["questionnaire"]["options"]=json!(["Different Fictional Name"]);report["questionnaire"]["step_sha256"]=json!(automated_apply_agents::execution::questionnaire_steps::step_hash(&work,&report["questionnaire"]));questionnaire_observe(&mut c,&work,report,&resumes).await.unwrap();assert!(questionnaire_prepare(&mut c,&resumes).await.unwrap());let held=browser_pref(&mut c,&format!("apply_work:{}",work["id"].as_str().unwrap())).await;assert_eq!(held["reason"],"questionnaire_saved_fact_does_not_fit_controls");assert_eq!(held["status"],"waiting");assert!(held["questionnaire_answer"].is_null());assert_eq!(sqlx::query_scalar::<_,i64>("SELECT count(*) FROM owner_preferences WHERE starts_with(key,'exec_q:')").fetch_one(&mut c).await.unwrap(),0);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_questionnaire_preparation_reuses_only_a_separately_approved_current_owner_bank_record(){
    let(mut c,work,q,resumes)=queue_question_fixture().await;let name:String=sqlx::query_scalar("SELECT full_name FROM candidate_profiles WHERE singleton_key='primary'").fetch_one(&mut c).await.unwrap();queue_owner_answer(&mut c,&q,&name,&resumes).await.unwrap();automated_apply_agents::execution::owner_questions::approve_reuse(&mut c,q["id"].as_str().unwrap().parse().unwrap(),&packet_settings()).await.unwrap();let key=format!("apply_work:{}",work["id"].as_str().unwrap());let mut pending=browser_pref(&mut c,&key).await;pending["operation"]=json!("prepare_questionnaire");pending["status"]=json!("queued");pending.as_object_mut().unwrap().remove("questionnaire_answer");browser_save(&mut c,&key,pending).await;assert!(questionnaire_prepare(&mut c,&resumes).await.unwrap());let saved=browser_pref(&mut c,&key).await;assert_eq!(saved["questionnaire_answer"]["source"],"owner_approved_reuse");assert_eq!(saved["questionnaire_answer"]["question_id"],q["id"]);assert_eq!(saved["admitted_actions"],work["admitted_actions"]);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_questionnaire_answer_admission_rechecks_retained_direct_fact_proof_before_any_additional_budget(){
    let(mut c,work,resumes)=questionnaire_fixture().await;queued_questionnaire(&mut c,&work,"What is your full name?",&resumes).await;assert!(questionnaire_prepare(&mut c,&resumes).await.unwrap());let key=format!("apply_work:{}",work["id"].as_str().unwrap());let mut prepared=browser_pref(&mut c,&key).await;prepared["operation"]=json!("answer_questionnaire");prepared["status"]=json!("leased");prepared["binding"]=work["form_binding"].clone();prepared["form_binding"]=work["form_binding"].clone();prepared["lease_token"]=json!(Uuid::new_v4());prepared["lease_until"]=json!((chrono::Utc::now()+chrono::Duration::seconds(180)).to_rfc3339());let now=chrono::Utc::now().to_rfc3339();prepared["facts"]["provider_resume_checked_at"]=json!(now);prepared["account_observation"]=json!({"source":"profile_ui","work_id":prepared["id"],"account_sha256":prepared["account_sha256"],"profile_document_id":"fictional-fresh-profile-document","observed_at":now,"binding":prepared["binding"]});prepared["questionnaire_answer"]["answer"]=json!("Conflicting Fictional Name");browser_save(&mut c,&key,prepared.clone()).await;let before=browser_snapshot(&mut c).await;let packets=packet_settings();assert_eq!(automated_apply_agents::execution::admission::admit(&mut c,sync_request(&prepared),automated_apply_agents::execution::admission::Services{packets:&packets,resumes:&resumes}).await.unwrap_err(),Failure("questionnaire_grounded_context_changed"));assert_eq!(browser_snapshot(&mut c).await,before);
}
